      margin-bottom: 0.5rem;
      font-size: 1.45rem;
      letter-spacing: -0.03em;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .dialog-note {
