             </p>
             <p class="status-message success" aria-live="polite" aria-atomic="true">
               ${state.statusMessage}
             </p>
           </div>
         </section>
       `;
     }

     function DetailsPanel() {
       return `
         <aside class="card meta-panel" aria-labelledby="details-title">
           <h2 id="details-title">Asset details</h2>
           <p class="meta-copy">A compact summary for quick moderation and housekeeping tasks.</p>
           <dl class="meta-list">
             <div class="meta-row">
               <dt class="meta-term">Format</dt>
               <dd class="meta-value">SVG illustration</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Dimensions</dt>
               <dd class="meta-value">1600 x 1200</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Collection</dt>
               <dd class="meta-value">Brand campaigns</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Last edited</dt>
               <dd class="meta-value">Today at 3:42 PM</dd>
             </div>
           </dl>
         </aside>
       `;
     }

     function ConfirmDeleteDialog() {
       return `
         <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
           <div class="dialog-body">
             <h2 id="delete-dialog-title" class="dialog-title">Delete this image from your library?</h2>
             <p id="delete-dialog-description" class="dialog-copy">
               Summit Dawn will be permanently removed from your saved assets. This action cannot be undone.
             </p>
             <p class="dialog-note">You can still cancel now and keep the image in your library.</p>
             <div class="dialog-actions">
               <button type="button" class="button-secondary" id="cancel-delete" autofocus>Cancel</button>
               <button type="button" class="button-danger" id="confirm-delete">Delete image</button>
             </div>
           </div>
         </dialog>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           ${Header()}
           <main id="maincontent" tabindex="-1">
             <div class="content-grid">
               ${state.isDeleted ? EmptyState() : ImagePreviewCard()}
               ${DetailsPanel()}
             </div>
           </main>
         </div>
         ${ConfirmDeleteDialog()}
       `;
     }

     function bindEvents() {
       const dialog = document.getElementById("delete-dialog");
       const trigger = document.getElementById("open-delete-dialog");
       const cancelButton = document.getElementById("cancel-delete");
       const confirmButton = document.getElementById("confirm-delete");

       if (trigger) {
         trigger.addEventListener("click", () => {
           if (!dialog.open) {
             dialog.showModal();
           }
         });
       }

       cancelButton.addEventListener("click", () => {
         dialog.close("cancel");
       });

       confirmButton.addEventListener("click", () => {
         state.isDeleted = true;
         state.statusMessage = "Summit Dawn was deleted from your library.";
         state.deletedJustNow = true;
         dialog.close("delete");
         render();
       });
     }

     function render() {
       const app = document.getElementById("app");
       app.innerHTML = App();
       bindEvents();

       if (state.deletedJustNow) {
         const deletedHeading = document.getElementById("deleted-heading");
         if (deletedHeading) {
           deletedHeading.focus();
         }
         state.deletedJustNow = false;
       }
     }

     render();
   </script>
