        .map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
    };
  });

  await page.click('#open-delete-dialog');

  const modal = await page.evaluate(async () => {
    const dialog = document.getElementById('delete-dialog');
    return {
      dialogOpen: dialog.open,
      activeId: document.activeElement && document.activeElement.id,
      violations: (await axe.run()).violations
        .filter(v => !(v.tags || []).includes('best-practice'))
        .map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
    };
  });

  await browser.close();
  console.log(JSON.stringify({ initial, modal }, null, 2));
  process.exit(initial.violations.length || modal.violations.length || initial.dialogOpen || !initial.triggerClass || modal.activeId !== 'cancel-delete' ? 1 : 0);
})().catch(err => {
  console.error(err.stack || err.message || String(err));
  process.exit(2);
});
