 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Image preview - Northstar Library</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f3f6fb;
       --panel: rgba(255, 255, 255, 0.9);
       --panel-strong: #ffffff;
       --text: #132238;
       --muted: #526277;
       --border: rgba(19, 34, 56, 0.12);
       --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
       --accent: #2f6fed;
       --accent-strong: #1f54bd;
       --danger: #c73a39;
       --danger-strong: #a32624;
       --success: #0f7b56;
       --surface: #e9eef8;
       --focus: #0b57d0;
     }

     * {
       box-sizing: border-box;
     }

     html, body {
       margin: 0;
       min-height: 100%;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top left, rgba(85, 125, 255, 0.15), transparent 28%),
         radial-gradient(circle at top right, rgba(46, 196, 182, 0.16), transparent 22%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       color: var(--text);
     }

     body {
       line-height: 1.5;
     }

     a,
     button {
       font: inherit;
     }

     button {
       border: 0;
       border-radius: 999px;
       cursor: pointer;
       transition: transform 120ms ease, background-color 120ms ease, border-color 120ms ease, box-shadow 120ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible,
     a:focus-visible,
     dialog:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       background: #ffffff;
       color: var(--text);
       border-radius: 0.75rem;
       box-shadow: var(--shadow);
       transform: translateY(-160%);
     }

     .skip-link:focus {
       transform: translateY(0);
       z-index: 20;
     }

     .page-shell {
       width: min(1120px, calc(100% - 2rem));
       margin: 0 auto;
       padding: 2rem 0 4rem;
     }

     .topbar {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       margin-bottom: 2.5rem;
       color: var(--muted);
     }

     .brand {
       display: inline-flex;
       align-items: center;
       gap: 0.8rem;
       font-weight: 700;
       color: var(--text);
     }

     .brand-mark {
       width: 2.25rem;
       height: 2.25rem;
       border-radius: 0.8rem;
       background: linear-gradient(135deg, #2f6fed 0%, #6ea6ff 100%);
       box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45);
     }

     .content-grid {
       display: grid;
       grid-template-columns: minmax(0, 1.75fr) minmax(280px, 1fr);
       gap: 1.5rem;
       align-items: start;
     }

     .card {
       background: var(--panel);
       border: 1px solid var(--border);
       border-radius: 1.5rem;
       box-shadow: var(--shadow);
       backdrop-filter: blur(16px);
     }

     .preview-card {
       overflow: hidden;
     }

     .image-frame {
       margin: 0;
       background: linear-gradient(180deg, #eff5ff 0%, #dde8fb 100%);
       aspect-ratio: 4 / 3;
       overflow: hidden;
     }

     .image-frame img {
       display: block;
       width: 100%;
       height: 100%;
       object-fit: cover;
     }

     .preview-body,
     .meta-panel {
       padding: 1.5rem;
     }

     .eyebrow {
       display: inline-flex;
       padding: 0.35rem 0.7rem;
       border-radius: 999px;
       background: rgba(47, 111, 237, 0.1);
       color: var(--accent-strong);
       font-size: 0.9rem;
       font-weight: 700;
     }

     h1,
     h2,
     h3,
     p {
       margin-top: 0;
     }

     .title {
       margin: 0.9rem 0 0.5rem;
       font-size: clamp(2rem, 3vw, 3rem);
       line-height: 1.08;
       letter-spacing: -0.04em;
     }

     .lede,
     .meta-copy,
     .dialog-copy,
     .status-message {
       color: var(--muted);
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.85rem;
       margin-top: 1.5rem;
     }

     .button-primary,
     .button-secondary,
     .button-danger {
       min-height: 2.875rem;
       padding: 0.8rem 1.2rem;
       font-weight: 700;
     }

     .button-primary {
       background: var(--accent);
       color: #ffffff;
       box-shadow: 0 10px 24px rgba(47, 111, 237, 0.28);
     }

     .button-primary:hover,
     .button-primary:focus-visible {
       background: var(--accent-strong);
     }

     .button-secondary {
       background: var(--panel-strong);
       color: var(--text);
       border: 1px solid var(--border);
     }

     .button-danger {
       background: rgba(199, 58, 57, 0.12);
       color: var(--danger-strong);
       border: 1px solid rgba(199, 58, 57, 0.18);
     }

     .button-danger:hover,
     .button-danger:focus-visible {
       background: rgba(199, 58, 57, 0.18);
     }

     .meta-list {
       display: grid;
       gap: 1rem;
       margin: 0;
       padding: 0;
     }

     .meta-row {
       padding-bottom: 1rem;
       border-bottom: 1px solid var(--border);
     }

     .meta-row:last-child {
       padding-bottom: 0;
       border-bottom: 0;
     }

     .meta-term {
       font-size: 0.85rem;
       font-weight: 700;
       text-transform: uppercase;
       letter-spacing: 0.08em;
       color: var(--muted);
       margin-bottom: 0.25rem;
     }

     .meta-value {
       margin: 0;
       font-size: 1rem;
       font-weight: 700;
     }

     .status {
       min-height: 1.5rem;
       margin-top: 1rem;
     }

     .status-message {
       margin: 0;
       font-weight: 600;
     }

     .status-message.success {
       color: var(--success);
     }

     .empty-state {
       display: grid;
       place-items: center;
       min-height: 420px;
       text-align: center;
       padding: 2rem;
       background:
         radial-gradient(circle at top, rgba(47, 111, 237, 0.14), transparent 34%),
         var(--panel);
     }

     .empty-state h2 {
       font-size: 1.7rem;
       letter-spacing: -0.03em;
     }

     dialog {
       width: min(100% - 2rem, 30rem);
       padding: 0;
       border: 1px solid var(--border);
       border-radius: 1.5rem;
       background: var(--panel-strong);
       box-shadow: 0 40px 80px rgba(15, 23, 42, 0.32);
       color: var(--text);
     }

     dialog::backdrop {
       background: rgba(15, 23, 42, 0.6);
       backdrop-filter: blur(6px);
     }

     .dialog-body {
       padding: 1.5rem;
     }

     .dialog-title {
       margin-bottom: 0.5rem;
       font-size: 1.45rem;
       letter-spacing: -0.03em;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       flex-wrap: wrap;
       gap: 0.75rem;
       margin-top: 1.5rem;
     }

     .dialog-note {
       padding: 0.85rem 1rem;
       border-radius: 1rem;
       background: var(--surface);
       color: var(--text);
       font-size: 0.95rem;
     }

     @media (max-width: 800px) {
       .content-grid {
         grid-template-columns: 1fr;
       }

       .topbar {
         flex-direction: column;
         align-items: flex-start;
       }
     }

     @media (max-width: 480px) {
       .page-shell {
         width: min(100% - 1rem, 1120px);
         padding-top: 1rem;
       }

       .preview-body,
       .meta-panel,
       .dialog-body {
         padding: 1.1rem;
       }

       .actions,
       .dialog-actions {
         flex-direction: column;
       }

       .button-primary,
       .button-secondary,
       .button-danger {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       button,
       dialog,
       .card,
       .skip-link {
         border: 1px solid CanvasText;
       }

       dialog::backdrop {
         background: rgba(0, 0, 0, 0.7);
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <div id="app"></div>

   <script>
     const state = {
       isDeleted: false,
       statusMessage: "",
       deletedJustNow: false
     };

     const imageSource = "data:image/svg+xml;charset=UTF-8," + encodeURIComponent(
       '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1200">' +
       '<defs>' +
       '<linearGradient id="sky" x1="0%" x2="0%" y1="0%" y2="100%">' +
       '<stop offset="0%" stop-color="#7ab1ff"/>' +
       '<stop offset="65%" stop-color="#d9ebff"/>' +
       '<stop offset="100%" stop-color="#f6ead6"/>' +
       '</linearGradient>' +
       '<linearGradient id="mountain" x1="0%" x2="100%" y1="0%" y2="100%">' +
       '<stop offset="0%" stop-color="#5b77a9"/>' +
       '<stop offset="100%" stop-color="#1c3558"/>' +
       '</linearGradient>' +
       '</defs>' +
       '<rect width="1600" height="1200" fill="url(#sky)"/>' +
       '<circle cx="1180" cy="240" r="96" fill="#fff2c2"/>' +
       '<path d="M0 860L280 560L430 700L655 410L840 650L1020 430L1265 720L1435 590L1600 790V1200H0Z" fill="url(#mountain)"/>' +
       '<path d="M0 925L270 710L430 800L710 570L960 865L1210 660L1600 930V1200H0Z" fill="#3f5e88" opacity="0.75"/>' +
       '<rect x="0" y="900" width="1600" height="300" fill="#18304f"/>' +
       '</svg>'
     );

     function Header() {
       return `
         <header class="topbar">
           <div class="brand">
             <span class="brand-mark" aria-hidden="true"></span>
             <span>Northstar Library</span>
           </div>
           <div>Image management</div>
         </header>
       `;
     }

     function ImagePreviewCard() {
       return `
         <article class="card preview-card" aria-labelledby="image-title">
           <figure class="image-frame">
             <img
               src="${imageSource}"
               alt="Preview of the Summit Dawn landscape artwork"
               width="1600"
               height="1200"
             >
           </figure>
           <div class="preview-body">
             <span class="eyebrow">Image preview</span>
             <h1 id="image-title" class="title">Summit Dawn</h1>
             <p class="lede">
               Review details for this asset before sharing, downloading, or removing it from your library.
             </p>
             <div class="actions">
               <button type="button" class="button-secondary">Download</button>
               <button type="button" class="button-danger trigger" id="open-delete-dialog">
                 Delete image
               </button>
             </div>
             <div class="status" aria-live="polite" aria-atomic="true">
               ${state.statusMessage ? `<p class="status-message ${state.isDeleted ? "success" : ""}">${state.statusMessage}</p>` : ""}
             </div>
           </div>
         </article>
       `;
     }

     function EmptyState() {
       return `
         <section class="card empty-state" aria-labelledby="deleted-heading">
           <div>
             <span class="eyebrow">Library updated</span>
             <h1 id="deleted-heading" class="title" tabindex="-1">Image deleted</h1>
             <p class="lede">
               Summit Dawn has been removed from your library. You can continue browsing your remaining assets.
             </p>
             <p class="status-message success" aria-live="polite" aria-atomic="true">
               ${state.statusMessage}
             </p>
           </div>
         </section>
       `;
     }

     function DetailsPanel() {
       return `
         <aside class="card meta-panel" aria-labelledby="details-title">
           <h2 id="details-title">Asset details</h2>
           <p class="meta-copy">A compact summary for quick moderation and housekeeping tasks.</p>
           <dl class="meta-list">
             <div class="meta-row">
               <dt class="meta-term">Format</dt>
               <dd class="meta-value">SVG illustration</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Dimensions</dt>
               <dd class="meta-value">1600 x 1200</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Collection</dt>
               <dd class="meta-value">Brand campaigns</dd>
             </div>
             <div class="meta-row">
               <dt class="meta-term">Last edited</dt>
               <dd class="meta-value">Today at 3:42 PM</dd>
             </div>
           </dl>
         </aside>
       `;
     }

     function ConfirmDeleteDialog() {
       return `
         <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
           <div class="dialog-body">
             <h2 id="delete-dialog-title" class="dialog-title">Delete this image from your library?</h2>
             <p id="delete-dialog-description" class="dialog-copy">
               Summit Dawn will be permanently removed from your saved assets. This action cannot be undone.
             </p>
             <p class="dialog-note">You can still cancel now and keep the image in your library.</p>
             <div class="dialog-actions">
               <button type="button" class="button-secondary" id="cancel-delete" autofocus>Cancel</button>
               <button type="button" class="button-danger" id="confirm-delete">Delete image</button>
             </div>
           </div>
         </dialog>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           ${Header()}
           <main id="maincontent" tabindex="-1">
             <div class="content-grid">
               ${state.isDeleted ? EmptyState() : ImagePreviewCard()}
               ${DetailsPanel()}
             </div>
           </main>
         </div>
         ${ConfirmDeleteDialog()}
       `;
     }

     function bindEvents() {
       const dialog = document.getElementById("delete-dialog");
       const trigger = document.getElementById("open-delete-dialog");
       const cancelButton = document.getElementById("cancel-delete");
       const confirmButton = document.getElementById("confirm-delete");

       if (trigger) {
         trigger.addEventListener("click", () => {
           if (!dialog.open) {
             dialog.showModal();
           }
         });
       }

       cancelButton.addEventListener("click", () => {
         dialog.close("cancel");
       });

       confirmButton.addEventListener("click", () => {
         state.isDeleted = true;
         state.statusMessage = "Summit Dawn was deleted from your library.";
         state.deletedJustNow = true;
         dialog.close("delete");
         render();
       });
     }

     function render() {
       const app = document.getElementById("app");
       app.innerHTML = App();
       bindEvents();

       if (state.deletedJustNow) {
         const deletedHeading = document.getElementById("deleted-heading");
         if (deletedHeading) {
           deletedHeading.focus();
         }
         state.deletedJustNow = false;
       }
     }

     render();
   </script>
 </body>
 </html>

')
